// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;

    function setUp() public {
        c = new RoundFactory();
        c.initialize();
    }

    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0));

        // owner is address(this) after initialize; transfer to the fuzzed newOwner
        c.transferOwnership(newOwner);

        // Rule: the new owner retains owner-level capability on C
        vm.prank(newOwner);
        bool ok = true;
        try c.updateAlloSettings(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}
